#!/usr/bin/env python3
"""Stage compact CI evidence while preserving immutable crash images."""
# Some portions generated by Codex
from __future__ import annotations

import argparse
import gzip
import hashlib
import json
import shutil
from pathlib import Path
from typing import Any, Callable


_GUEST_EVIDENCE_SUFFIXES = {".json", ".log", ".sha256", ".txt"}
_GUEST_EVIDENCE_NAMES = {"SHA256SUMS"}
_EXCLUDED_GUEST_SUFFIXES = {".fd", ".img", ".iso", ".qcow2"}


def _sha256(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as stream:
        for block in iter(lambda: stream.read(1024 * 1024), b""):
            digest.update(block)
    return digest.hexdigest()


def _copy_file(source: Path, source_root: Path, output_root: Path, copied: list[str]) -> None:
    if source.is_symlink() or not source.is_file():
        raise ValueError(f"refusing non-regular evidence input: {source}")
    relative = source.relative_to(source_root)
    destination = output_root / relative
    destination.parent.mkdir(parents=True, exist_ok=True)
    shutil.copyfile(source, destination)
    copied.append(relative.as_posix())


def _compress_crash_image(source: Path, source_root: Path, output_root: Path,
                          images: list[dict[str, Any]]) -> None:
    if source.is_symlink() or not source.is_file():
        raise ValueError(f"refusing non-regular crash image: {source}")
    relative = source.relative_to(source_root)
    package_relative = relative.with_name(relative.name + ".gz")
    destination = output_root / package_relative
    destination.parent.mkdir(parents=True, exist_ok=True)
    original_digest = hashlib.sha256()
    original_size = 0
    with source.open("rb") as raw, destination.open("xb") as compressed_file:
        with gzip.GzipFile(filename="", mode="wb", compresslevel=1,
                           fileobj=compressed_file, mtime=0) as compressed:
            for block in iter(lambda: raw.read(1024 * 1024), b""):
                original_digest.update(block)
                original_size += len(block)
                compressed.write(block)
    images.append({
        "source_path": relative.as_posix(),
        "package_path": package_relative.as_posix(),
        "encoding": "gzip",
        "original_size_bytes": original_size,
        "original_sha256": original_digest.hexdigest(),
        "compressed_size_bytes": destination.stat().st_size,
        "compressed_sha256": _sha256(destination),
    })


def _copy_tree(source_root: Path, output_root: Path, directory: str,
               predicate: Callable[[Path], bool] | None = None) -> list[str]:
    source_directory = source_root / directory
    copied: list[str] = []
    if not source_directory.exists():
        return copied
    if source_directory.is_symlink() or not source_directory.is_dir():
        raise ValueError(f"refusing non-directory evidence root: {source_directory}")
    for path in sorted(source_directory.rglob("*")):
        if path.is_symlink():
            raise ValueError(f"refusing symlink in evidence tree: {path}")
        if not path.is_file() or (predicate is not None and not predicate(path)):
            continue
        _copy_file(path, source_root, output_root, copied)
    return copied


def package_ci_evidence(source_root: Path, output_root: Path) -> dict[str, Any]:
    source_root = source_root.resolve()
    output_root = output_root.resolve()
    if output_root == source_root or source_root in output_root.parents:
        raise ValueError("artifact output must be outside the crashlab workspace")
    output_root.mkdir(parents=True, exist_ok=False)

    copied: list[str] = []
    images: list[dict[str, Any]] = []
    campaigns = source_root / "campaigns"
    if campaigns.exists():
        if campaigns.is_symlink() or not campaigns.is_dir():
            raise ValueError(f"refusing non-directory campaign evidence: {campaigns}")
        for name in ("ci-campaign-command-plan.json", "ci-campaign-failure.json",
                     "ci-campaign-summary.json", "ci-gate-summary.json"):
            path = campaigns / name
            if path.exists():
                _copy_file(path, source_root, output_root, copied)
        for results in sorted(campaigns.glob("*/results")):
            if results.is_symlink() or not results.is_dir():
                raise ValueError(f"refusing non-directory results path: {results}")
            for path in sorted(results.rglob("*")):
                if path.is_symlink():
                    raise ValueError(f"refusing symlink in campaign results: {path}")
                if not path.is_file():
                    continue
                if path.name == "data.raw" and path.parent.name == "pre-recovery-image":
                    _compress_crash_image(path, source_root, output_root, images)
                else:
                    _copy_file(path, source_root, output_root, copied)
        runner_logs = campaigns / "runner-logs"
        if runner_logs.exists():
            copied.extend(_copy_tree(source_root, output_root, "campaigns/runner-logs",
                                     lambda path: path.suffix.lower() == ".log"))
        for qemu_logs in sorted(campaigns.glob("*/qemu")):
            if qemu_logs.is_symlink() or not qemu_logs.is_dir():
                raise ValueError(f"refusing non-directory QEMU setup path: {qemu_logs}")
            for path in sorted(qemu_logs.rglob("*.log")):
                if path.is_symlink():
                    raise ValueError(f"refusing symlink in QEMU setup logs: {path}")
                if path.is_file():
                    _copy_file(path, source_root, output_root, copied)

    copied.extend(_copy_tree(source_root, output_root, "kvm-preflight"))
    copied.extend(_copy_tree(source_root, output_root, "maven"))

    def is_guest_evidence(path: Path) -> bool:
        if path.suffix.lower() in _EXCLUDED_GUEST_SUFFIXES:
            return False
        return path.suffix.lower() in _GUEST_EVIDENCE_SUFFIXES or path.name in _GUEST_EVIDENCE_NAMES

    copied.extend(_copy_tree(source_root, output_root, "guest", is_guest_evidence))
    for name in ("host-classpath.txt", "host-dependencies.txt"):
        path = source_root / name
        if path.exists():
            _copy_file(path, source_root, output_root, copied)

    manifest = {
        "format_version": 1,
        "crash_images": sorted(images, key=lambda image: image["source_path"]),
        "preserved_files": sorted(set(copied)),
        "excluded_regenerable_inputs": [
            "campaigns/*/data/",
            "campaigns/*/qemu/ binary overlays, firmware copies, and seed ISOs",
            "campaigns/*/working-recovery-*/",
            "guest cloud images, QEMU overlays, firmware variable copies, and seed ISOs; checksum metadata is retained",
        ],
    }
    (output_root / "artifact-manifest.json").write_text(
        json.dumps(manifest, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    return manifest


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--crashlab-root", type=Path, required=True)
    parser.add_argument("--output-root", type=Path, required=True)
    args = parser.parse_args()
    manifest = package_ci_evidence(args.crashlab_root, args.output_root)
    total = sum(path.stat().st_size for path in args.output_root.rglob("*") if path.is_file())
    print(f"packaged {len(manifest['preserved_files'])} evidence files and "
          f"{len(manifest['crash_images'])} compressed crash images ({total} bytes)")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
